function startSurvey(r:Room){resetPlayersForGame(r.players);const settings=r.settings.survey||{},maxQuestions=Number(settings.maxQuestions??5);if(!Number.isInteger(maxQuestions)||maxQuestions<1||maxQuestions>20)err('アンケート数は1〜20問にしてください。','invalid-argument');const questionOrder=Object.values(r.players).filter(player=>player.connected).map(player=>player.uid);for(let i=questionOrder.length-1;i>0;i--){const j=randomInt(i+1);[questionOrder[i],questionOrder[j]]=[questionOrder[j],questionOrder[i]]}r.settings.gameType='survey';r.pointBreakdown??={};r.replayVotes={};r.replayNeedsConfig=false;r.winner=null;r.endedAt=undefined;r.miniGame={type:'survey',source:settings.source==='host'?'host':'sequential',maxQuestions,questionIndex:0,questionOrder,questions:[],currentQuestion:null,finished:false,startedAt:Date.now()};r.phase='survey-question';r.round=1;r.paused=false;r.deadline=null;r.remaining=0;r.lobbyReady={};r.startedAt=Date.now();r.endedAt=undefined;log(r,'survey-start','匿名アンケートを開始しました。')}
