function finishOgiriJudging(r:Room){const g=r.miniGame;if(g?.type!=='ogiri'||r.phase!=='ogiri-judge')return;const active=Object.values(r.players).filter(p=>p.alive&&p.connected&&!p.hold&&!g.eliminated.includes(p.uid));const answerUids=Object.keys(g.answers||{}),complete=(judgeUid:string)=>ogiriRatingsComplete(ogiriJudgeTargets(r,judgeUid),g.ratings?.[judgeUid]);if(g.settings.judgeMode==='host'){if(!complete(managerUid(r)))return}else if(active.some(judge=>!complete(judge.uid)))return;g.roundScores=ogiriRoundScores(answerUids,g.ratings||{},g.settings.scoring);g.roundRanking=answerUids.map(uid=>({uid,name:r.players[uid]?.name||'不明',average:g.roundScores[uid].average,votes:g.roundScores[uid].votes})).sort((a:any,b:any)=>b.average-a.average||a.name.localeCompare(b.name,'ja'));r.phase='ogiri-result';r.deadline=null;r.remaining=0;log(r,'ogiri-judged',`第${g.round}問の採点を集計しました。`)}
