 const s=defaults(Number(q.data?.playerCount)||8,q.data?.settings);s.gameType='jinrou';const raw=['shared','hybrid'].includes(s.method)&&Array.isArray(s.sharedPlayers)?s.sharedPlayers:[],names=raw.map((x:any)=>String(x?.name||'').trim());
 if(!['personal','room'].includes(s.themeScope))s.themeScope='personal';
 if(s.themeScope==='room'&&s.visualPreset){const preset=s.visualPreset,assets=preset.assets&&typeof preset.assets==='object'?preset.assets:{};if(preset.version!==1||!/^[-A-Za-z0-9_]{8,80}$/.test(String(preset.id||''))||Object.keys(assets).length>80)err('世界観プリセットの形式が正しくありません。','invalid-argument');let total=0;for(const [id,item] of Object.entries(assets) as [string,any][]){if(!/^[-A-Za-z0-9_]{8,100}$/.test(id)||!item||typeof item!=='object')err('共有素材の識別情報が正しくありません。','invalid-argument');const bytes=Number(item.bytes||0);if(!Number.isFinite(bytes)||bytes<0||bytes>25*1024*1024)err('共有素材は1ファイル25MBまでです。','invalid-argument');total+=bytes;assets[id]={name:String(item.name||'素材').slice(0,120),mime:String(item.mime||'').slice(0,80),bytes}}if(total>80*1024*1024)err('共有素材の合計は80MBまでです。','invalid-argument');s.visualPreset={...preset,assets};if(JSON.stringify(s.visualPreset).length>250_000)err('プリセット情報が大きすぎます。素材を減らしてください。','invalid-argument')}else delete s.visualPreset;
 if(!['individual','shared','hybrid'].includes(s.method))err('参加方法が正しくありません。','invalid-argument');
 if(!['player','gm'].includes(s.hostMode))err('ホストの参加方法が正しくありません。','invalid-argument');if(['shared','hybrid'].includes(s.method)&&s.hostMode!=='player')err('共有端末を使う場合、ホストはプレイヤーとして参加してください。','failed-precondition');
