 const perTurn=Number(s.nightSeconds??30);if(!Number.isInteger(perTurn)||perTurn<30||perTurn>600||perTurn%30!==0)err('1人あたりの夜の行動時間は30秒〜10分、30秒単位で設定してください。','invalid-argument');s.nightSeconds=perTurn;
 if(s.method==='shared'&&Number(s.roles?.共有者||0)>0)err('全員共有モードでは共有者を設定できません。','invalid-argument');
 if(s.method==='hybrid'&&Number(s.roles?.共有者||0)!==0&&Number(s.roles?.共有者||0)!==2)err('併用モードの共有者は0人または2人に設定してください。','invalid-argument');
 if(s.method==='hybrid'&&Number(s.roles?.共有者||0)===2&&Number(s.playerCount)-names.length<2)err('共有者を設定するには、各自の端末を使うプレイヤーが2人以上必要です。','failed-precondition');
